190	 * the group is NAMED for the owner (a shared `users` / macOS `staff` fails — their member lists are empty for primary members,
191	 * so emptiness alone never proved privacy: audit LOW-001), no account but the owner is a listed member, no other account has
192	 * it as its primary group (enumerated last), and no ACL makes the group bits a mask over named grants (`ls -ldL`'s `+`, on
193	 * the read's own descriptor when one is given). Accounts come from `getent`; a host without it, or one that cannot answer,
194	 * is no proof: not private.
195	 */
196	export function agyGroupNotPrivate(uid: number, gid: number, fd?: number, configPath?: string): string | undefined {
197	  const pw = (getent(["passwd", String(uid)]) ?? "").split("\n")[0].split(":");
198	  const owner = pw[0] ?? "";
199	  const pgid = pw[3] ?? "";
200	  if (!owner || !/^\d+$/.test(pgid)) return `its owner uid ${uid} could not be looked up`;
201	  const gr = (getent(["group", String(gid)]) ?? "").split("\n")[0].split(":");
202	  const gname = gr[0] ?? "";
203	  if (!gname) return `its group could not be looked up (gid ${gid})`;
204	  if (String(gid) !== pgid) return `its group '${gname}' (gid ${gid}) is not the owner's primary group`;
205	  if (gname !== owner) return `its group '${gname}' is not named for the owner '${owner}' (not a user-private group)`;
206	  const members = (gr[3] ?? "").split(",").map((m) => m.trim()).filter((m) => m && m !== owner);
207	  if (members.length) return `its group '${gname}' has other members (${members.join(", ")})`;
208	  const all = getent(["passwd"]);
209	  if (all === undefined) return `the accounts of group '${gname}' could not be enumerated`;
210	  const primary = all.split("\n").map((l) => l.split(":")).filter((f) => f.length > 3 && f[3] === String(gid) && f[2] !== String(uid)).map((f) => f[0]);
211	  if (primary.length) return `its group '${gname}' is the primary group of another account (${primary.join(", ")})`;
212	  let ls = "";
213	  try {
214	    ls = fd !== undefined
215	      ? execFileSync("ls", ["-ldL", "/dev/stdin"], { encoding: "utf8", timeout: 5000, stdio: [fd, "pipe", "ignore"] })
216	      : execFileSync("ls", ["-ldL", "--", configPath ?? ""], { encoding: "utf8", timeout: 5000, stdio: ["ignore", "pipe", "ignore"] });
217	  } catch {
218	    ls = "";
219	  }
220	  const lsMode = ls.split(" ")[0] ?? "";
221	  if (lsMode.length < 10) return "its ACL could not be read";
222	  if (lsMode[10] === "+") return "it carries an extended ACL (the group bits are the ACL mask over other accounts' grants)";
223	  return undefined;
224	}
