235	export function agyConfigUntrustedReason(
236	  configPath: string, st?: { uid: number; gid: number; mode: number }, fd?: number,
237	): string | undefined {
238	  if (st === undefined) {
239	    try {
240	      st = statSync(configPath);
241	    } catch {
242	      return `${configPath} could not be stat'ed (owner and mode unknown)`;
243	    }
244	  }
245	  const me = typeof process.getuid === "function" ? process.getuid() : undefined;
246	  if (me !== undefined && st.uid !== me) return `${configPath} is not owned by the current user (uid ${st.uid}, euid ${me})`;
247	  const mode = `mode ${(st.mode & 0o7777).toString(8).padStart(4, "0")}`;
248	  if (st.mode & 0o002) return `${configPath} is world-writable (${mode})`;
249	  if (st.mode & 0o020) {
250	    const why = agyGroupNotPrivate(st.uid, st.gid, fd, configPath);
251	    if (why !== undefined) return `${configPath} is group-writable (${mode}) and ${why}`;
252	  }
253	  return undefined;
