256	/**
257	 * Read `hounfour.headless.agy_opt_in` (true only for a YAML boolean true) and `hounfour.headless.mode` from the Loa config
258	 * with one yq call. LOA_HEADLESS_MODE wins for the mode, as it does in cheval; nothing in the environment opts in. A missing
259	 * file reads as off; a missing yq or an unreadable config reads as off too (the gate fails closed) and carries `readError`.
260	 */
261	export function readAgyGate(configPath: string): AgyGate {
262	  let optIn = false;
263	  let mode = "";
264	  let readError: string | undefined;
265	  let typeWarning: string | undefined;
266	  if (existsSync(configPath)) {
267	    let fd: number | undefined;
268	    let content: Buffer | undefined;
269	    try {
270	      // (r251-6 V3, BB #2: the config is opened ONCE — yq parses the bytes read from this descriptor on stdin and the trust
271	      // rule judges its fstat, so a swap of the path between read and check changes nothing)
272	      fd = openSync(configPath, "r");
273	      const st = fstatSync(fd);
274	      if (!st.isFile()) throw new Error(`${configPath} is not a regular file`);
275	      content = readFileSync(fd);
276	      const out = execFileSync(
277	        "yq",
278	        ["eval", "-o=json", "-I=0",
279	          `{"has": (${AGY_YQ_HAS}), "kind": (.hounfour.headless.agy_opt_in | kind), "opt": (.hounfour.headless.agy_opt_in | (tag == "!!bool" and . == true)), "canon": (.hounfour.headless.agy_opt_in | (tag == "!!bool" and (. == true or . == false))), "tag": (.hounfour.headless.agy_opt_in | tag), "mode": (.hounfour.headless.mode // ""), ${AGY_YQ_ANCESTORS}}`,
280	          "-"],
281	        { encoding: "utf8", timeout: 5000, input: content, stdio: ["pipe", "pipe", "pipe"] },
282	      );
283	      const parsed = JSON.parse(out) as {
284	        has?: unknown; kind?: unknown; opt?: unknown; canon?: unknown; tag?: unknown; mode?: unknown;
285	        k1?: unknown; t1?: unknown; k2?: unknown; t2?: unknown;
286	      };
287	      // (r251-4 S3: the key must be written at hounfour.headless itself — every level a real mapping, never an alias or a
288	      // merge key's value — and its node a plain scalar of the exact bool tag; one rule with the bash and Python readers)
289	      const present = parsed.has === true;
290	      const alias = parsed.kind === "alias";
291	      optIn = present && !alias && parsed.opt === true;
292	      mode = typeof parsed.mode === "string" ? parsed.mode : "";
293	      const ancestor = present ? undefined : agyAncestorProblem(parsed);
294	      // (r251-5 U1: a config others can write never opts in — one WARN naming the key and the reason; not a readError:
295	      // the gate reads off, exactly as the bash and Python readers, rather than blocking the merge. Only a value that
296	      // would opt in is judged, as there: a config that reads off anyway is not flagged)
297	      const untrusted = optIn ? agyConfigUntrustedReason(configPath, st, fd) : undefined;
298	      if (untrusted !== undefined) {
299	        optIn = false;
300	        typeWarning = `hounfour.headless.agy_opt_in: ${untrusted} — a config others can write never opts in (own it and \`chmod go-w\` it); the agy route stays off`;
301	      } else if (ancestor !== undefined) {
302	        typeWarning = `${ancestor} — hounfour.headless.agy_opt_in cannot be read through an alias or merge node (write the mapping inline); the agy route stays off`;
303	      } else if (present && alias) {
304	        typeWarning = "hounfour.headless.agy_opt_in is present but not a YAML boolean (an alias) — only `agy_opt_in: true` opts in (expected true or false); the agy route stays off";
305	      } else if (present && typeof parsed.tag === "string" && parsed.tag !== "!!null" && parsed.tag !== "!!bool") {
306	        typeWarning = `hounfour.headless.agy_opt_in is present but not a YAML boolean (${parsed.tag}) — only \`agy_opt_in: true\` opts in (expected true or false); the agy route stays off`;
307	      } else if (present && parsed.tag === "!!bool" && parsed.canon !== true) {
308	        typeWarning = "hounfour.headless.agy_opt_in is a boolean spelled other than true/false — only `agy_opt_in: true` opts in (the lowercase scalar); the agy route stays off";
309	      }
310	    } catch (err) {
311	      // (fail closed: no opt-in — and say why, rather than reading as a plain "opt-in off")
312	      const e = err as { stderr?: unknown; message?: string };
313	      const stderr = typeof e.stderr === "string" ? e.stderr.trim() : Buffer.isBuffer(e.stderr) ? e.stderr.toString("utf8").trim() : "";
