315	      // (r251-6 V5: a non-mapping ancestor yq cannot index below — `headless: [1]` — is the ancestor warning the bash and
316	      // Python readers give, not a host read error; the same bytes, the guarded ancestors-only program)
317	      const ancestor = content !== undefined ? agyAncestorOnly(content) : undefined;
318	      if (ancestor !== undefined) {
319	        typeWarning = `${ancestor} — hounfour.headless.agy_opt_in cannot be read through an alias or merge node (write the mapping inline); the agy route stays off`;
320	      } else {
321	        readError = (stderr || e.message || String(err)).split("\n")[0].slice(0, 300);
322	      }
323	    } finally {
