326	  }
327	  return {
328	    optIn, mode: process.env.LOA_HEADLESS_MODE || mode || "prefer-api",
329	    ...(readError !== undefined ? { readError } : {}), ...(typeWarning !== undefined ? { typeWarning } : {}),
330	  };
331	}
