333	/** The ancestors' kind and tag (r251-6 V5): `hounfour`, and `hounfour.headless` only below a real mapping. */
334	export const AGY_YQ_ANCESTORS = '"k1": (.hounfour | kind), "t1": (.hounfour | tag), "k2": ((.hounfour | select(kind == "map") | .headless | kind) // ""), "t2": ((.hounfour | select(kind == "map") | .headless | tag) // "")';
