336	/** The ancestors-only read of `content` (never errors on a non-mapping level: each level is guarded); undefined on any failure. */
337	function agyAncestorOnly(content: Buffer): string | undefined {
338	  try {
339	    const out = execFileSync("yq", ["eval", "-o=json", "-I=0", `{${AGY_YQ_ANCESTORS}}`, "-"],
340	      { encoding: "utf8", timeout: 5000, input: content, stdio: ["pipe", "pipe", "pipe"] });
341	    return agyAncestorProblem(JSON.parse(out));
342	  } catch {
343	    return undefined;
344	  }
345	}
