349	 * mapping, absent or null. */
350	function agyAncestorProblem(p: { k1?: unknown; t1?: unknown; k2?: unknown; t2?: unknown }): string | undefined {
351	  for (const [path, k, t] of [["hounfour", p.k1, p.t1], ["hounfour.headless", p.k2, p.t2]] as const) {
352	    if (k === "map") continue;
353	    if (k === "alias") return `${path} is a YAML alias`;
354	    if (typeof t !== "string" || t === "" || t === "!!null") return undefined;
355	    return `${path} is not a mapping (${t.replace(/^!!/, "")})`;
356	  }
357	  return undefined;
358	}
