928	/**
929	 * Auto-detect owner/repo from git remote -v.
930	 */
931	async function autoDetectRepo(): Promise<{ owner: string; repo: string } | null> {
932	  try {
933	    const { stdout } = await execFileAsync("git", ["remote", "-v"], {
934	      timeout: 5_000,
935	    });
936	    const lines = stdout.split("\n");
937	    const ghPattern = /(?:github\.com)[:/]([^/\s]+)\/([^/\s.]+?)(?:\.git)?\s/;
938	    // Prefer "origin" remote — avoids picking framework remote alphabetically (#395)
939	    const originLine = lines.find(
940	      (l) => l.startsWith("origin\t") && l.includes("(fetch)"),
941	    );
942	    const targetLine = originLine ?? lines.find((l) => l.includes("(fetch)"));
943	    const match = targetLine?.match(ghPattern);
944	    if (match) {
945	      return { owner: match[1], repo: match[2] };
946	    }
947	    return null;
948	  } catch {
949	    return null;
950	  }
951	}
