956	function parseRepoString(s: string): { owner: string; repo: string } {
957	  const parts = s.split("/");
958	  if (parts.length !== 2 || !parts[0] || !parts[1]) {
959	    throw new Error(
960	      `Invalid repo format: "${s}". Expected "owner/repo".`,
961	    );
962	  }
963	  return { owner: parts[0], repo: parts[1] };
964	}
