966	// Decision: Pure regex YAML parser over yaml/js-yaml library.
967	// Zero runtime dependencies is a hard constraint for this skill (PRD NFR-1).
968	// The config surface is flat key:value pairs + simple lists — no anchors, aliases,
969	// multi-line strings, or nested objects needed. A full YAML parser (~50KB min)
970	// would add attack surface and supply chain risk for features we don't use.
971	// If nested config objects are ever needed, swap to js-yaml behind this function.
972	/**
973	 * Load YAML config from .loa.config.yaml if it exists.
974	 * Uses a simple key:value parser — no YAML library dependency.
975	 * Supports scalar values and YAML list syntax (- item).
976	 */
977	export async function loadYamlConfig(): Promise<YamlConfig> {
978	  try {
979	    const content = await readFile(".loa.config.yaml", "utf-8");
980	    // Find bridgebuilder section
981	    const match = content.match(/^bridgebuilder:\s*\n((?:[ \t]+.+\n?)*)/m);
982	    if (!match) return {};
983	
984	    const section = match[1];
985	    const config: YamlConfig = {};
986	    const lines = section.split("\n");
987	
988	    for (let i = 0; i < lines.length; i++) {
989	      const kv = lines[i].match(/^\s+([\w_]+):\s*(.*)/);
990	      if (!kv) continue;
991	      const [, key, rawValue] = kv;
992	      const value = rawValue.replace(/#.*$/, "").trim().replace(/^["']|["']$/g, "");
993	
994	      // Check if next lines are YAML list items (- value)
995	      if (value === "" || value === undefined) {
996	        const items: string[] = [];
997	        while (i + 1 < lines.length) {
998	          const listItem = lines[i + 1].match(/^\s+-\s+(.+)/);
999	          if (!listItem) break;
1000	          items.push(listItem[1].replace(/#.*$/, "").trim().replace(/^["']|["']$/g, ""));
1001	          i++;
1002	        }
1003	        if (items.length > 0) {
1004	          switch (key) {
1005	            case "repos":
1006	              config.repos = items;
1007	              break;
1008	            case "dimensions":
1009	              config.dimensions = items;
1010	              break;
1011	            case "exclude_patterns":
1012	              config.exclude_patterns = items;
1013	              break;
1014	          }
1015	          continue;
1016	        }
1017	      }
1018	
1019	      switch (key) {
1020	        case "enabled":
1021	          config.enabled = value === "true";
1022	          break;
1023	        case "model":
1024	          config.model = value;
1025	          break;
1026	        case "max_prs":
1027	          config.max_prs = Number(value);
1028	          break;
1029	        case "max_files_per_pr":
1030	          config.max_files_per_pr = Number(value);
1031	          break;
1032	        case "max_diff_bytes":
1033	          config.max_diff_bytes = Number(value);
1034	          break;
1035	        case "max_input_tokens":
1036	          config.max_input_tokens = Number(value);
1037	          break;
1038	        case "max_output_tokens":
1039	          config.max_output_tokens = Number(value);
1040	          break;
1041	        case "review_marker":
1042	          config.review_marker = value;
1043	          break;
1044	        case "persona_path":
1045	          config.persona_path = value;
1046	          break;
1047	        case "sanitizer_mode":
1048	          if (value === "default" || value === "strict") {
1049	            config.sanitizer_mode = value;
1050	          }
1051	          break;
1052	        case "max_runtime_minutes":
1053	          config.max_runtime_minutes = Number(value);
1054	          break;
1055	        case "loa_aware":
1056	          config.loa_aware = value === "true";
1057	          break;
1058	        case "persona":
1059	          config.persona = value;
1060	          break;
1061	        case "review_mode":
1062	          if (value === "two-pass" || value === "single-pass") {
1063	            config.review_mode = value;
1064	          }
1065	          break;
1066	        case "ecosystem_context_path":
1067	          config.ecosystem_context_path = value;
1068	          break;
1069	        case "pass1_cache_enabled":
1070	          config.pass1_cache_enabled = value === "true";
1071	          break;
1072	      }
1073	    }
1074	
1075	    return config;
1076	  } catch {
1077	    return {};
1078	  }
1079	}
