1119	/**
1120	 * Resolve config using 5-level precedence: CLI > env > yaml > auto-detect > defaults.
1121	 * Returns config and provenance (where each key value came from).
1122	 */
1123	export async function resolveConfig(
1124	  cliArgs: CLIArgs,
1125	  env: EnvVars,
1126	  yamlConfig?: YamlConfig,
1127	): Promise<{ config: BridgebuilderConfig; provenance: ConfigProvenance }> {
1128	  const yaml = yamlConfig ?? (await loadYamlConfig());
1129	
1130	  // Check enabled flag from YAML
1131	  if (yaml.enabled === false) {
1132	    throw new Error(
1133	      "Bridgebuilder is disabled in .loa.config.yaml. Set bridgebuilder.enabled: true to enable.",
1134	    );
1135	  }
1136	
1137	  // Build repos list: first-non-empty-wins (CLI > env > yaml > auto-detect)
1138	  let repos: Array<{ owner: string; repo: string }> = [];
1139	  let reposSource: ConfigSource = "default";
1140	
1141	  // CLI --repo flags (highest priority)
1142	  if (cliArgs.repos?.length) {
1143	    for (const r of cliArgs.repos) {
1144	      repos.push(parseRepoString(r));
1145	    }
1146	    reposSource = "cli";
1147	  }
1148	
1149	  // Env BRIDGEBUILDER_REPOS (comma-separated) — only if CLI didn't set repos
1150	  if (repos.length === 0 && env.BRIDGEBUILDER_REPOS) {
1151	    for (const r of env.BRIDGEBUILDER_REPOS.split(",")) {
1152	      const trimmed = r.trim();
1153	      if (trimmed) repos.push(parseRepoString(trimmed));
1154	    }
1155	    if (repos.length > 0) reposSource = "env";
1156	  }
1157	
1158	  // YAML repos — only if no higher-priority source set repos
1159	  if (repos.length === 0 && yaml.repos?.length) {
1160	    for (const r of yaml.repos) {
1161	      repos.push(parseRepoString(r));
1162	    }
1163	    reposSource = "yaml";
1164	  }
1165	
1166	  // Auto-detect (unless --no-auto-detect) — only if no explicit repos configured
1167	  if (repos.length === 0 && !cliArgs.noAutoDetect) {
1168	    const detected = await autoDetectRepo();
1169	    if (detected) {
1170	      repos.push(detected);
1171	      reposSource = "auto-detect";
1172	    }
1173	  }
1174	
1175	  if (repos.length === 0) {
1176	    throw new Error(
1177	      "No repos configured. Use --repo owner/repo, set BRIDGEBUILDER_REPOS, or run from a git repo.",
1178	    );
1179	  }
1180	
1181	  // Track model provenance (CLI > env > yaml > default)
1182	  const modelSource: ConfigSource = cliArgs.model
1183	    ? "cli"
1184	    : env.BRIDGEBUILDER_MODEL
1185	      ? "env"
1186	      : yaml.model
1187	        ? "yaml"
1188	        : "default";
1189	
1190	  // Track dryRun provenance
1191	  const dryRunSource: ConfigSource = cliArgs.dryRun != null
1192	    ? "cli"
1193	    : env.BRIDGEBUILDER_DRY_RUN === "true"
1194	      ? "env"
1195	      : "default";
1196	
1197	  // Track token/size provenance
1198	  const maxInputTokensSource: ConfigSource = cliArgs.maxInputTokens != null
1199	    ? "cli"
1200	    : yaml.max_input_tokens != null
1201	      ? "yaml"
1202	      : "default";
1203	  const maxOutputTokensSource: ConfigSource = cliArgs.maxOutputTokens != null
1204	    ? "cli"
1205	    : yaml.max_output_tokens != null
1206	      ? "yaml"
1207	      : "default";
1208	  const maxDiffBytesSource: ConfigSource = cliArgs.maxDiffBytes != null
1209	    ? "cli"
1210	    : yaml.max_diff_bytes != null
1211	      ? "yaml"
1212	      : "default";
1213	
1214	  // Resolve repoRoot: CLI > env > git auto-detect (Bug 3 fix — issue #309)
1215	  const repoRoot = resolveRepoRoot(cliArgs, env);
1216	
1217	  // Resolve remaining fields: CLI > env > yaml > defaults
1218	  const config: BridgebuilderConfig = {
1219	    repos,
1220	    repoRoot,
1221	    model:
1222	      cliArgs.model ?? env.BRIDGEBUILDER_MODEL ?? yaml.model ?? DEFAULTS.model,
1223	    maxPrs: yaml.max_prs ?? DEFAULTS.maxPrs,
1224	    maxFilesPerPr: yaml.max_files_per_pr ?? DEFAULTS.maxFilesPerPr,
1225	    maxDiffBytes: cliArgs.maxDiffBytes ?? yaml.max_diff_bytes ?? DEFAULTS.maxDiffBytes,
1226	    maxInputTokens: cliArgs.maxInputTokens ?? yaml.max_input_tokens ?? DEFAULTS.maxInputTokens,
1227	    maxOutputTokens: cliArgs.maxOutputTokens ?? yaml.max_output_tokens ?? DEFAULTS.maxOutputTokens,
1228	    dimensions: yaml.dimensions ?? DEFAULTS.dimensions,
1229	    reviewMarker: yaml.review_marker ?? DEFAULTS.reviewMarker,
1230	    repoOverridePath: yaml.persona_path ?? DEFAULTS.repoOverridePath,
1231	    dryRun:
1232	      cliArgs.dryRun ??
1233	      (env.BRIDGEBUILDER_DRY_RUN === "true" ? true : undefined) ??
1234	      DEFAULTS.dryRun,
1235	    excludePatterns: [
1236	      ...(yaml.exclude_patterns ?? []),
1237	      ...(cliArgs.exclude ?? []),
1238	    ],
1239	    sanitizerMode: yaml.sanitizer_mode ?? DEFAULTS.sanitizerMode,
1240	    maxRuntimeMinutes: yaml.max_runtime_minutes ?? DEFAULTS.maxRuntimeMinutes,
1241	    ...(cliArgs.pr != null ? { targetPr: cliArgs.pr } : {}),
1242	    ...(yaml.loa_aware != null ? { loaAware: yaml.loa_aware } : {}),
1243	    ...(cliArgs.persona != null || yaml.persona != null
1244	      ? { persona: cliArgs.persona ?? yaml.persona }
1245	      : {}),
1246	    ...(yaml.persona_path != null
1247	      ? { personaFilePath: yaml.persona_path }
1248	      : {}),
1249	    ...(cliArgs.forceFullReview ? { forceFullReview: true } : {}),
1250	    ...(yaml.ecosystem_context_path != null
1251	      ? { ecosystemContextPath: yaml.ecosystem_context_path }
1252	      : {}),
1253	    ...(resolvePass1Cache(cliArgs, env, yaml) != null
1254	      ? { pass1Cache: { enabled: resolvePass1Cache(cliArgs, env, yaml)! } }
1255	      : {}),
1256	    reviewMode:
1257	      cliArgs.reviewMode ??
1258	      (env.LOA_BRIDGE_REVIEW_MODE === "two-pass" || env.LOA_BRIDGE_REVIEW_MODE === "single-pass"
1259	        ? env.LOA_BRIDGE_REVIEW_MODE
1260	        : undefined) ??
1261	      yaml.review_mode ??
1262	      DEFAULTS.reviewMode,
1263	  };
1264	
1265	  // Track reviewMode provenance
1266	  const reviewModeSource: ConfigSource = cliArgs.reviewMode
1267	    ? "cli"
1268	    : env.LOA_BRIDGE_REVIEW_MODE === "two-pass" || env.LOA_BRIDGE_REVIEW_MODE === "single-pass"
1269	      ? "env"
1270	      : yaml.review_mode
1271	        ? "yaml"
1272	        : "default";
1273	
1274	  const provenance: ConfigProvenance = {
1275	    repos: reposSource,
1276	    model: modelSource,
1277	    dryRun: dryRunSource,
1278	    maxInputTokens: maxInputTokensSource,
1279	    maxOutputTokens: maxOutputTokensSource,
1280	    maxDiffBytes: maxDiffBytesSource,
1281	    reviewMode: reviewModeSource,
1282	  };
1283	
1284	  return { config, provenance };
