47	/**
48	 * Parse optional YAML frontmatter from persona content (V3-2).
49	 * Returns the model override (if any) and the content without frontmatter.
50	 */
51	export function parsePersonaFrontmatter(raw: string): { content: string; model?: string } {
52	  const match = raw.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
53	  if (!match) return { content: raw };
54	
55	  const frontmatter = match[1];
56	  const content = match[2];
57	
58	  // Extract model field from frontmatter (simple key: value parsing)
59	  const modelMatch = frontmatter.match(/^\s*model:\s*(.+?)\s*$/m);
60	  const model = modelMatch?.[1]?.replace(/^["']|["']$/g, "");
61	
62	  // Ignore commented-out model lines (# model: ...)
63	  if (model && model.startsWith("#")) return { content };
64	
65	  return { content, model: model || undefined };
66	}
