103	/**
104	 * Summarize the persona resolution cascade for `--show-persona-resolution`.
105	 * Returns an ordered list of cascade levels with whether each is active,
106	 * skipped (input not provided), or shadowed (input provided but a higher
107	 * level won). The active level is the one `loadPersona()` will return.
108	 */
109	export interface PersonaResolutionStep {
110	  level: number;
111	  name: string;
112	  state: "active" | "skip" | "shadow" | "missing";
113	  value?: string;
114	  reason?: string;
115	}
116	
117	export async function traceResolution(
118	  config: BridgebuilderConfig,
119	): Promise<PersonaResolutionStep[]> {
120	  const packName = config.persona;
121	  const customPath = config.personaFilePath;
122	  const repoOverridePath = config.repoOverridePath;
123	
124	  const steps: PersonaResolutionStep[] = [];
125	  let activeFound = false;
126	
127	  // Level 1: --persona CLI flag / Level 2: persona: YAML (both resolve to pack name)
128	  if (packName) {
129	    const packPath = resolve(PERSONAS_DIR, `${packName}.md`);
130	    let packExists = false;
131	    try {
132	      await readFile(packPath, "utf-8");
133	      packExists = true;
134	    } catch {
135	      packExists = false;
136	    }
137	    steps.push({
138	      level: 1,
139	      name: "--persona flag / persona: YAML",
140	      state: packExists ? "active" : "missing",
141	      value: packName,
142	      reason: packExists
143	        ? `pack file: ${packPath}`
144	        : `pack file not found: ${packPath}`,
145	    });
146	    if (packExists) activeFound = true;
147	  } else {
148	    steps.push({
149	      level: 1,
150	      name: "--persona flag / persona: YAML",
151	      state: "skip",
152	      reason: "not provided",
153	    });
154	  }
155	
156	  // Level 3: persona_path → custom file
157	  if (customPath) {
158	    let customExists = false;
159	    try {
160	      await readFile(customPath, "utf-8");
161	      customExists = true;
162	    } catch {
163	      customExists = false;
164	    }
165	    const state = activeFound
166	      ? "shadow"
167	      : customExists
168	      ? "active"
169	      : "missing";
170	    steps.push({
171	      level: 3,
172	      name: "persona_path: YAML",
173	      state,
174	      value: customPath,
175	      reason: customExists
176	        ? undefined
177	        : state === "missing"
178	        ? `file not found: ${customPath}`
179	        : undefined,
180	    });
181	    if (state === "active") activeFound = true;
182	  } else {
183	    steps.push({
184	      level: 3,
185	      name: "persona_path: YAML",
186	      state: "skip",
187	      reason: "not provided",
188	    });
189	  }
190	
191	  // Level 4: repo override (grimoires/bridgebuilder/BEAUVOIR.md)
192	  if (repoOverridePath) {
193	    let repoExists = false;
194	    try {
195	      await readFile(repoOverridePath, "utf-8");
196	      repoExists = true;
197	    } catch {
198	      repoExists = false;
199	    }
200	    const state = activeFound
201	      ? "shadow"
202	      : repoExists
203	      ? "active"
204	      : "missing";
205	    steps.push({
206	      level: 4,
207	      name: "repo override (BEAUVOIR.md)",
208	      state,
209	      value: repoOverridePath,
210	      reason: repoExists
211	        ? undefined
212	        : state === "missing"
213	        ? `file not found: ${repoOverridePath}`
214	        : undefined,
215	    });
216	    if (state === "active") activeFound = true;
217	  } else {
218	    steps.push({
219	      level: 4,
220	      name: "repo override (BEAUVOIR.md)",
221	      state: "skip",
222	      reason: "not provided",
223	    });
224	  }
225	
226	  // Level 5: built-in default
227	  const defaultPath = resolve(PERSONAS_DIR, "default.md");
228	  steps.push({
229	    level: 5,
230	    name: "built-in default",
231	    state: activeFound ? "shadow" : "active",
232	    value: defaultPath,
233	  });
234	
235	  return steps;
236	}
