238	/**
239	 * Format persona resolution steps for terminal display.
240	 */
241	export function formatResolutionTrace(steps: PersonaResolutionStep[]): string {
242	  const lines: string[] = ["persona resolution:"];
243	  for (const step of steps) {
244	    const marker =
245	      step.state === "active"
246	        ? "[active]"
247	        : step.state === "shadow"
248	        ? "[shadow]"
249	        : step.state === "missing"
250	        ? "[missing]"
251	        : "[skip]  ";
252	    const head = `  ${marker} L${step.level} ${step.name}`;
253	    const tail = step.value ? `: ${step.value}` : "";
254	    const note = step.reason ? `  (${step.reason})` : "";
255	    lines.push(`${head}${tail}${note}`);
256	  }
257	  return lines.join("\n");
258	}
