260	/**
261	 * Load persona using 5-level CLI-wins precedence chain:
262	 * 1. --persona <name> CLI flag → resources/personas/<name>.md
263	 * 2. persona: <name> YAML config → resources/personas/<name>.md
264	 * 3. persona_path: <path> YAML config → load custom file path
265	 * 4. grimoires/bridgebuilder/BEAUVOIR.md (repo-level override)
266	 * 5. resources/personas/default.md (built-in default)
267	 *
268	 * Returns { content, source } for logging.
269	 */
270	export async function loadPersona(
271	  config: BridgebuilderConfig,
272	  logger?: { warn: (msg: string) => void },
273	): Promise<{ content: string; source: string; model?: string }> {
274	  const repoOverridePath = config.repoOverridePath;
275	  const packName = config.persona;
276	  const customPath = config.personaFilePath;
277	
278	  // Level 1 & 2: --persona CLI or persona: YAML (both resolve to pack name)
279	  if (packName) {
280	    const packPath = resolve(PERSONAS_DIR, `${packName}.md`);
281	    try {
282	      const raw = await readFile(packPath, "utf-8");
283	      const { content, model } = parsePersonaFrontmatter(raw);
284	
285	      // Warn if repo override exists but is being ignored
286	      if (repoOverridePath) {
287	        try {
288	          await readFile(repoOverridePath, "utf-8");
289	          logger?.warn(
290	            `Using --persona ${packName} (repo override at ${repoOverridePath} ignored)`,
291	          );
292	        } catch {
293	          // Repo override doesn't exist — no warning needed
294	        }
295	      }
296	
297	      return { content, source: `pack:${packName}`, model };
298	    } catch {
299	      // Unknown persona — list available packs
300	      const available = await discoverPersonas();
301	      throw new Error(
302	        `Unknown persona "${packName}". Available: ${available.join(", ")}`,
303	      );
304	    }
305	  }
306	
307	  // Level 3: persona_path: YAML config → load custom file path
308	  if (customPath) {
309	    try {
310	      const raw = await readFile(customPath, "utf-8");
311	      const { content, model } = parsePersonaFrontmatter(raw);
312	      return { content, source: `custom:${customPath}`, model };
313	    } catch {
314	      throw new Error(`Persona file not found at custom path: "${customPath}".`);
315	    }
316	  }
317	
318	  // Level 4: Repo-level override (grimoires/bridgebuilder/BEAUVOIR.md)
319	  if (repoOverridePath) {
320	    try {
321	      const raw = await readFile(repoOverridePath, "utf-8");
322	      const { content, model } = parsePersonaFrontmatter(raw);
323	      return { content, source: `repo:${repoOverridePath}`, model };
324	    } catch {
325	      // Fall through to default
326	    }
327	  }
328	
329	  // Level 5: Built-in default persona
330	  const defaultPath = resolve(PERSONAS_DIR, "default.md");
331	  try {
332	    const raw = await readFile(defaultPath, "utf-8");
333	    const { content, model } = parsePersonaFrontmatter(raw);
334	    return { content, source: "pack:default", model };
335	  } catch {
336	    // Fallback to legacy BEAUVOIR.md next to main.ts
337	    const legacyPath = resolve(__dirname, "BEAUVOIR.md");
338	    try {
339	      const raw = await readFile(legacyPath, "utf-8");
340	      const { content, model } = parsePersonaFrontmatter(raw);
341	      return { content, source: `legacy:${legacyPath}`, model };
342	    } catch {
343	      throw new Error(
344	        `No persona found. Expected at "${defaultPath}" or "${legacyPath}".`,
345	      );
346	    }
347	  }
348	}
