353	  for (const r of summary.results) {
354	    if (r.skipReason) {
355	      skipReasons[r.skipReason] = (skipReasons[r.skipReason] ?? 0) + 1;
356	    }
357	  }
358	
359	  // Build error code distribution
360	  const errorCodes: Record<string, number> = {};
361	  for (const r of summary.results) {
362	    if (r.error) {
363	      errorCodes[r.error.code] = (errorCodes[r.error.code] ?? 0) + 1;
364	    }
365	  }
366	
367	  console.log(
368	    JSON.stringify(
369	      {
370	        runId: summary.runId,
371	        reviewed: summary.reviewed,
372	        skipped: summary.skipped,
373	        errors: summary.errors,
374	        startTime: summary.startTime,
375	        endTime: summary.endTime,
376	        verdicts: summary.results.map((result) => ({
377	          repo: `${result.item.owner}/${result.item.repo}`,
378	          pr: result.item.pr.number,
379	          headSha: result.item.pr.headSha,
380	          verdict: result.verdict ?? "UNKNOWN",
381	          highestSeverity: result.highestSeverity ?? null,
382	          mergeBlocked: result.mergeBlocked ?? true,
383	        })),
384	        ...(Object.keys(skipReasons).length > 0 ? { skipReasons } : {}),
385	        ...(Object.keys(errorCodes).length > 0 ? { errorCodes } : {}),
386	      },
387	      null,
388	      2,
389	    ),
390	  );
391	}
