11	        .filter((r) => r.response !== undefined && r.error === undefined)
12	        .map((r) => `${r.provider}/${r.model}`);
13	    // (an older pipeline result without voicesPlanned: every attempted voice was planned)
14	    const plannedLabels = result.voicesPlanned ?? result.modelResults.map((r) => `${r.provider}/${r.model}`);
15	    const remaining = [...completedLabels];
16	    const incomplete = [];
17	    for (const label of plannedLabels) {
18	        const i = remaining.indexOf(label);
19	        if (i >= 0)
20	            remaining.splice(i, 1);
21	        else
22	            incomplete.push(label);
23	    }
24	    const band = computeVerdictBand(result.modelResults.map((r) => ({ verdictQuality: r.response?.verdictQuality })));
25	    const completed = completedLabels.length;
26	    const planned = plannedLabels.length;
27	    return {
28	        planned,
29	        completed,
30	        band,
31	        incomplete,
32	        degraded: completed < planned || band === "DEGRADED" || band === "FAILED",
